const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TWO = 6.28318530718, PI = Math.PI, INV2PI = 0.15915494309;
const BW = 190, BH = Math.max(56, Math.round(BW * height / width));
