  S.baseAng = fr(1) * TWO;     // seed orientation of the fixed-point axis
  S.hoff = fr(2) * 360;         // seed hue offset
  S.tw = fr(3) * 0.9 + 0.6;     // seed twist bias
  S.px = (fr(4) - 0.5) * 0.6;   // seed vortex-center jitter
