const flowBreath = Math.sin(K.t * 0.11 * (0.5 + P.speed)) * (0.55 + A.bass * 0.9); // loxodromic in/out toward fixed points
const orbit = K.t * 0.031;                                                       // fixed points slowly revolve
const hueDrift = K.t * 0.016 + K.section * 0.055;                                 // slow palette drift + section arc
const expo = 0.45 + P.energy * 0.6 + K.intensity * 0.25 + A.rms * 0.55;

