const sepR = 0.14 + P.sep * 1.35 + 0.22 * Math.sin(K.t * 0.023);  // fixed-point separation breathes over minutes
const sa = S.baseAng + orbit;
const spx = sepR * Math.cos(sa), spy = sepR * Math.sin(sa);
