      const mCk = 0.5 + 0.5 * Math.tanh(sc * 3.5);
      const m = frac(ct * 0.11 + lmF * 0.05 + hueDrift);
      const c = pal(m);
      const bright = (0.30 + 0.62 * mCk) * expo;
      const tint2 = 0.85 + 0.3 * mCk;
      r = c[0] * bright; gg = c[1] * bright * tint2; bb = c[2] * bright;
    }
    const o = 4 * (j * BW + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, bb * 255));
